<script setup lang="ts">import { onMounted, ref } from 'vue'; import { useRoute } from 'vue-router'; import { strategiesApi } from '../api/services'; import AppLoading from '../components/AppLoading.vue'; import type { StrategyHistory } from '../types/api'; const route = useRoute(); const rows = ref<StrategyHistory[]>([]); const loading = ref(true); onMounted(async () => { rows.value = await strategiesApi.history(String(route.params.id)); loading.value = false })</script>
<template><section class="page"><div class="page-heading"><div><p class="eyebrow">AUDITORIA</p><h1>Histórico da estratégia</h1></div></div><AppLoading v-if="loading"/><div v-else class="timeline"><article v-for="item in rows" :key="item.revision"><strong>Revisão {{ item.revision }} · {{ item.operation }}</strong><p>{{ item.title }} · {{ item.category }} · {{ item.campaign }}</p><small>{{ item.changedAt }}</small></article></div></section></template>
